const stamp = () => new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Africa/Lagos', year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', hour12: false
}).format(new Date());   // e.g. 2026-11-23 09:10 (Lagos time)


const data = $json.body || $json;

const customerId = String(data['Customer ID'] || data.customer_id || '').trim();
const contactName = String(data['Contact Name'] || data.contact_name || '').trim();
const email = String(data['Email Address'] || data.email || '').trim();
const businessName = String(data['Business Name'] || data.business_name || '').trim();
const question = String(data['Support Question'] || data.support_question || '').trim();
const additionalInfo = String(data['Additional Information'] || data.additional_information || '').trim();

const errors = [];

if (!customerId) errors.push('Customer ID is required.');
if (!contactName) errors.push('Contact name is required.');
if (!businessName) errors.push('Business name is required.');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  errors.push('A valid email address is required.');
}
if (!question) errors.push('Support question is required.');

return {
  json: {
    support_id: `SUP-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
    customer_id: customerId,
    contact_name: contactName,
    email,
    business_name: businessName,
    customer_question: question,
    additional_information: additionalInfo,
    submitted_at: stamp(),
    is_valid: errors.length === 0,
    validation_errors: errors
  }
};

