const raw = $('AI Support Analysis').first().json;
const request = $('Validate Support Request').first().json;

// Find the AI's list of issues, even if nested (a single old-style answer is wrapped in a list).
function findRequests(value) {
  if (!value) return null;

  if (typeof value === 'string') {
    try {
      return findRequests(JSON.parse(value));
    } catch {
      return null;
    }
  }

  if (typeof value !== 'object') return null;

  if (Array.isArray(value.requests) && value.requests.length > 0) return value.requests;

  if (Object.prototype.hasOwnProperty.call(value, 'ai_draft_response')) return [value];

  for (const nestedValue of Object.values(value)) {
    const result = findRequests(nestedValue);
    if (result) return result;
  }

  return null;
}

const issues = (findRequests(raw) || [])
  .filter(item => item && item.ai_draft_response)
  .slice(0, 10);

// Fallback: never lose a customer's question because the AI step failed.
// The whole message is saved as one row, flagged for escalation and left for a human to triage.
if (issues.length === 0) {
  return [{
    json: {
      support_id: request.support_id,
      customer_id: request.customer_id,
      submitted_at: request.submitted_at,
      customer_question: request.customer_question,
      category: 'UNCATEGORISED',
      priority: 'MEDIUM',
      ai_draft_response: 'AI analysis unavailable - needs manual triage.',
      escalation_required: true,
      escalation_reason: 'AI analysis failed',
      status: 'ESCALATED',
      human_response: ''
    }
  }];
}

// Keep the sheet clean: fixed category list, and status is just OPEN or ESCALATED
const allowedCategories = ['ONBOARDING', 'DOCUMENTATION', 'TECHNICAL', 'COMPLIANCE', 'PAYMENT', 'GENERAL'];
const allowedPriorities = ['LOW', 'MEDIUM', 'HIGH', 'CRITICAL'];

// One sheet row per issue
return issues.map((ai, index) => {
  const category = String(ai.category || '').trim().toUpperCase();
  const priority = String(ai.priority || '').trim().toUpperCase();
  const escalated = ai.escalation_required === true ||
    String(ai.escalation_required).trim().toLowerCase() === 'true';

  return {
    json: {
      support_id: issues.length > 1 ? `${request.support_id}-${index + 1}` : request.support_id,
      customer_id: request.customer_id,
      submitted_at: request.submitted_at,
      customer_question: String(ai.customer_question || '').trim() || request.customer_question,
      category: allowedCategories.includes(category) ? category : 'GENERAL',
      priority: allowedPriorities.includes(priority) ? priority : 'MEDIUM',
      ai_draft_response: ai.ai_draft_response,
      escalation_required: escalated,
      escalation_reason: ai.escalation_reason || '',
      status: escalated ? 'ESCALATED' : 'OPEN',
      human_response: ''
    }
  };
});

const stamp = () => new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Africa/Lagos', year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', hour12: false
}).format(new Date());   // e.g. 2026-11-23 09:10 (Lagos time)

const customers = $('Get Customers').all()
  .map(item => item.json)
  .filter(row => row.customer_id);

const tasks = $('Get Tasks').all()
  .map(item => item.json)
  .filter(row => row.task_id);

const supportRequests = $('Get Support Requests').all()
  .map(item => item.json)
  .filter(row => row.support_id);

const followUps = $('Get Follow-Up Log').all()
  .map(item => item.json)
  .filter(row => row.followup_id);

const upper = v => String(v || '').trim().toUpperCase();

const totalCustomers = customers.length;

// A customer is COMPLETED when they have tasks and every task is COMPLETED
const tasksByCustomer = new Map();
for (const task of tasks) {
  const id = String(task.customer_id);
  if (!tasksByCustomer.has(id)) tasksByCustomer.set(id, []);
  tasksByCustomer.get(id).push(task);
}

const completedCustomers = customers.filter(c => {
  const list = tasksByCustomer.get(String(c.customer_id)) || [];
  return list.length > 0 && list.every(t => upper(t.status) === 'COMPLETED');
}).length;

const pendingCustomers = totalCustomers - completedCustomers;

const outstandingTasks = tasks.filter(row =>
  ['PENDING', 'IN_PROGRESS'].includes(upper(row.status))
).length;

const openSupport = supportRequests.filter(row =>
  !['RESOLVED', 'CLOSED'].includes(upper(row.status))
);

const unresolvedSupportRequests = openSupport.length;

const escalatedOpen = openSupport.filter(row =>
  String(row.escalation_required).toLowerCase() === 'true'
).length;

const sentFollowUps = followUps.filter(row => upper(row.status) === 'SENT').length;
const failedFollowUps = followUps.filter(row => upper(row.status) === 'FAILED').length;

const reportSummary = `
MANAGEMENT REPORT

Total customers: ${totalCustomers}
Customers still onboarding: ${pendingCustomers}
Customers fully onboarded: ${completedCustomers}
Outstanding onboarding tasks: ${outstandingTasks}
Unresolved support requests: ${unresolvedSupportRequests}
  of which escalated to a human: ${escalatedOpen}
Follow-up emails sent: ${sentFollowUps}
Follow-up emails failed: ${failedFollowUps}

This report was generated automatically by the onboarding prototype.
Support requests remain subject to human review.
`.trim();

return [{
  json: {
    report_id: `RPT-${Date.now()}`,
    generated_at: stamp(),
    total_customers: totalCustomers,
    pending_customers: pendingCustomers,
    completed_customers: completedCustomers,
    outstanding_tasks: outstandingTasks,
    unresolved_support_requests: unresolvedSupportRequests,
    report_summary: reportSummary
  }
}];
